function.arguments:
{"command": "cd /workspace && cat > /tmp/ptyrun.py <<'EOF'
import os, pty, sys, select, fcntl, termios, struct, time, subprocess, signal

def run(cmd, rows=24, cols=80, input_bytes=b'', wait=1.0, env=None):
    pid, fd = pty.fork()
    if pid == 0:
        if env: os.environ.update(env)
        try:
            os.execvp(cmd[0], cmd)
        except Exception:
            os._exit(1)
    fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack('HHHH', rows, cols, 0, 0))
    out = b''
    t0 = time.time()
    if input_bytes:
        os.write(fd, input_bytes)
    while time.time() - t0 < wait:
        r,_,_ = select.select([fd], [], [], 0.1)
        if r:
            try:
                data = os.read(fd, 65536)
            except OSError:
                break
            if not data: break
            out += data
    try:
        os.kill(pid, signal.SIGKILL)
    except Exception: pass
    os.waitpid(pid, 0)
    return out

if __name__ == '__main__':
    import json
    spec = json.loads(sys.argv[1])
    out = run(spec['cmd'], spec.get('rows',24), spec.get('cols',80), spec.get('input','').encode(), spec.get('wait',1.0))
    sys.stdout.buffer.write(out)
EOF
python3 /tmp/ptyrun.py '{"cmd":["./executable","--help"],"cols":40}' | cat -A | head -40"}

