import ptytest as P
def clean(s):
    return re.sub(r'\x1b\[[0-9;?]*[a-zA-Z]','',s.decode('utf8',errors='replace'))
def words(n, seed=0):
    import itertools
    ws = ['lorem','ipsum','dolor','sit','amet','consectetur','adipiscing','elit','sed','do','eiusmod','tempor','incididunt','ut','labore','et','dolore','magna','aliqua','enim']
