// ---------------------------------------------------------------------------
// Parser producing nlohmann::json compatible error messages
// ---------------------------------------------------------------------------
struct ParseError {
    std::string message;  // full message including the prefix
};

namespace detail {
inline std::string utf8_error_string(const std::string& s) {
    std::string out;
    for (unsigned char c : s) {
        if (c < 0x20) {
            char buf[16];
            std::snprintf(buf, sizeof(buf), "<U+%.4X>", c);
            out += buf;
        } else {
            out += static_cast<char>(c);
        }
    }
    return out;
}

inline const char* control_name(int cp) {
    static const char* names[32] = {
        "NUL", "SOH", "STX", "ETX", "EOT", "ENQ", "ACK", "BEL",
        "BS",  "HT",  "LF",  "VT",  "FF",  "CR",  "SO",  "SI",
        "DLE", "DC1", "DC2", "DC3", "DC4", "NAK", "SYN", "ETB",
        "CAN", "EM",  "SUB", "ESC", "FS",  "GS",  "RS",  "US"};
    return names[cp & 31];
}
inline const char* control_escape(int cp) {
    switch (cp) {
        case 0x08: return "b";
        case 0x09: return "t";
        case 0x0A: return "n";
        case 0x0C: return "f";
        case 0x0D: return "r";
        default: return nullptr;
    }
}
}  // namespace detail

struct Lexer {
    const unsigned char* data;
    size_t size;
    size_t pos = 0;
    // position tracking (nlohmann style)
    size_t lines_read = 0;
    size_t chars_read_current_line = 0;
    std::string token_string;
    std::string tok1, tok2;  // the two last classified tokens
    int current = -1;        // the current character (-1 == EOF)
    bool next_unget = false;
    bool utf8_error = false;

    explicit Lexer(const unsigned char* d, size_t n) : data(d), size(n) {}

    void get() {
        if (next_unget) {
            next_unget = false;
        } else {
            if (pos < size) {
                current = data[pos++];
            } else {
                current = -1;
            }
        }
        chars_read_current_line++;
        if (current == '\n') {
            lines_read++;
            chars_read_current_line = 0;
        }
        if (current >= 0)
            token_string.push_back(static_cast<char>(current));
        else
            token_string += "<EOF>";
    }

    void unget() {
        next_unget = true;
        chars_read_current_line--;
        if (current == '\n') {
            lines_read--;
            chars_read_current_line = 1;  // approximate
        }
        if (!token_string.empty()) {
            // keep the character (nlohmann keeps it in the error message)
        }
    }

    void reset_token() { token_string.assign(tok1 + tok2); }
    void classify(const std::string& s) {
        tok2 = tok1;
        tok1 = s;
    }
    std::string current_token() const {
        std::string pre = tok1 + tok2;
        if (token_string.size() > pre.size()) return token_string.substr(pre.size());
        return token_string;
    }
    void classify_current() { classify(current_token()); }

    int peek_next() {
        get();
        int c = current;
        unget();
        return c;
    }

    void skip_whitespace() {
        while (current == ' ' || current == '\t' || current == '\n' || current == '\r') get();
    }
};

enum class Tok {
    Uninitialized, EndOfInput, BeginArray, BeginObject, EndArray, EndObject,
    ValueSeparator, NameSeparator, String, Number, LiteralTrue, LiteralFalse,
    LiteralNull, LiteralOrValue
};

struct Parser {
    Lexer lex;
    std::string error;
    bool has_error = false;
    int error_line = 0, error_col = 0;
    bool out_of_range = false;

    explicit Parser(const unsigned char* d, size_t n) : lex(d, n) {}

    std::string prefix() const {
        char buf[64];
        std::snprintf(buf, sizeof(buf), "[json.exception.%s.%d] parse error at line %zu, column %zu: ",
                      out_of_range ? "out_of_range" : "parse_error", out_of_range ? 406 : 101,
                      lex.lines_read + 1, lex.chars_read_current_line);
        return buf;
    }

    std::string token_name(Tok t) const {
        switch (t) {
            case Tok::EndOfInput: return "end of input";
            case Tok::BeginArray: return "'['";
            case Tok::BeginObject: return "'{'";
            case Tok::EndArray: return "']'";
            case Tok::EndObject: return "'}'";
            case Tok::ValueSeparator: return "','";
            case Tok::NameSeparator: return "':'";
            case Tok::String: return "string literal";
            case Tok::Number: return "number literal";
            case Tok::LiteralTrue: return "true";
            case Tok::LiteralFalse: return "false";
            case Tok::LiteralNull: return "null";
            default: return "literal_or_value";
        }
    }

    std::string expected_name(Tok t) const {
        switch (t) {
            case Tok::EndOfInput: return "end of input";
            case Tok::BeginArray: return "'['";
            case Tok::BeginObject: return "'{'";
            case Tok::EndArray: return "']'";
            case Tok::EndObject: return "'}'";
            case Tok::ValueSeparator: return "','";
            case Tok::NameSeparator: return "':'";
            case Tok::String: return "string literal";
            case Tok::Number: return "number literal";
            case Tok::LiteralOrValue: return "'[', '{', or a literal";
            default: return "value";
        }
    }

    void fail(const std::string& context, const std::string& problem) {
        if (has_error) return;
        has_error = true;
        error_line = static_cast<int>(lex.lines_read + 1);
        error_col = static_cast<int>(lex.chars_read_current_line);
        error = prefix() + "syntax error while parsing " + context + " - " + problem;
    }

    // message when an unexpected token is found where `expected` was wanted
    void fail_token(Tok expected, const std::string& context) {
        if (has_error) return;
        std::string problem;
        if (last_token == Tok::LiteralOrValue) {
            problem = "invalid literal; last read: '" + detail::utf8_error_string(lex.token_string) + "'";
        } else if (last_token == Tok::EndOfInput) {
            problem = "unexpected end of input";
        } else {
            problem = "unexpected " + token_name(last_token);
        }
        problem += "; expected " + expected_name(expected);
        fail(context, problem);
    }

    // ------------------------------------------------------------------
    // token scanning
    // ------------------------------------------------------------------
    Tok last_token = Tok::Uninitialized;

    bool scan_literal(const char* text, size_t n, Tok ret) {
        size_t i = 0;
        for (; i < n; i++) {
            lex.get();
            if (lex.current == -1) break;
            if (static_cast<char>(lex.current) != text[i]) break;
        }
        if (i == n) {
            lex.classify_current();
            return true;
        }
