// JSON value model, parser and scalar formatting that mimic the observable
// behaviour of the original program (nlohmann::json based).
#pragma once
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <memory>
#include <string>
#include <vector>

namespace json {

enum class Type { Null, Bool, Int, UInt, Double, String, Array, Object };

struct Value;
using Array = std::vector<Value>;
struct Object : std::vector<std::pair<std::string, Value>> {};  // sorted by key

struct Value {
    Type type = Type::Null;
    bool boolean = false;
    int64_t integer = 0;
    uint64_t uinteger = 0;
    double number = 0.0;
    std::string str;
    std::shared_ptr<Array> arr;
    std::shared_ptr<Object> obj;

    Value() = default;
    bool is_object() const { return type == Type::Object; }
    bool is_array() const { return type == Type::Array; }
    bool is_string() const { return type == Type::String; }
    bool is_number() const {
        return type == Type::Int || type == Type::UInt || type == Type::Double;
    }
};

// ---------------------------------------------------------------------------
// double formatting: shortest round-trip digits + nlohmann's layout rules
// ---------------------------------------------------------------------------
namespace detail {
inline void shortest_digits(double v, std::string& digits, int& exponent) {
    char buf[64];
    for (int prec = 0; prec <= 17; prec++) {
        std::snprintf(buf, sizeof(buf), "%.*e", prec, v);
        if (std::strtod(buf, nullptr) == v) break;
    }
    char* e = std::strchr(buf, 'e');
    int exp10 = e ? std::atoi(e + 1) : 0;
    std::string mant(buf, e ? static_cast<size_t>(e - buf) : std::strlen(buf));
    digits.clear();
    for (char c : mant)
        if (c != '.') digits += c;
    while (digits.size() > 1 && digits.back() == '0') digits.pop_back();
    exponent = exp10;
}

inline std::string to_string_uint(uint64_t v) {
    char buf[32];
    std::snprintf(buf, sizeof(buf), "%llu", static_cast<unsigned long long>(v));
    return buf;
}
inline std::string to_string_int(int64_t v) {
    char buf[32];
    std::snprintf(buf, sizeof(buf), "%lld", static_cast<long long>(v));
    return buf;
}
}  // namespace detail

inline std::string dump_number(const Value& v) {
    switch (v.type) {
        case Type::Int: return detail::to_string_int(v.integer);
        case Type::UInt: return detail::to_string_uint(v.uinteger);
        case Type::Double: {
            double value = v.number;
            if (value == 0.0) return std::signbit(value) ? "-0.0" : "0.0";
            bool neg = std::signbit(value);
            double av = neg ? -value : value;
            std::string digits;
            int exp10 = 0;
            detail::shortest_digits(av, digits, exp10);
            std::string out;
            if (neg) out += '-';
            // fixed notation when -4 <= exp <= 14
            if (exp10 >= -4 && exp10 <= 14) {
                if (exp10 >= 0) {
                    if (static_cast<int>(digits.size()) > exp10 + 1) {
                        out += digits.substr(0, exp10 + 1);
                        out += '.';
                        out += digits.substr(exp10 + 1);
                    } else {
                        out += digits;
                        out += std::string(static_cast<size_t>(exp10 + 1 - static_cast<int>(digits.size())), '0');
                        out += ".0";
                    }
                } else {
                    out += "0.";
                    out += std::string(static_cast<size_t>(-exp10 - 1), '0');
                    out += digits;
                }
            } else {
                out += digits.substr(0, 1);
                if (digits.size() > 1) {
                    out += '.';
                    out += digits.substr(1);
                }
                out += 'e';
                int a = exp10 < 0 ? -exp10 : exp10;
                char tmp[16];
                if (a < 10)
                    std::snprintf(tmp, sizeof(tmp), "%c%02d", exp10 < 0 ? '-' : '+', a);
                else
                    std::snprintf(tmp, sizeof(tmp), "%c%d", exp10 < 0 ? '-' : '+', a);
                out += tmp;
            }
            return out;
        }
        default: return "";
    }
}

