struct Glyph {
    std::string ch;
    int width;
};

inline std::vector<Glyph> split_glyphs(const std::string& s) {
    std::vector<Glyph> out;
    size_t i = 0;
    while (i < s.size()) {
        unsigned cp = 0;
        size_t start = i;
        utf8_next(s, i, cp);
        out.push_back({s.substr(start, i - start), char_width(cp)});
    }
    return out;
}

inline int display_width(const std::string& s) {
    int w = 0;
    for (auto& g : split_glyphs(s)) w += g.width;
    return w;
}

// ---------------------------------------------------------------------------
// tree model
// ---------------------------------------------------------------------------
struct Node {
    const json::Value* v = nullptr;
    std::string key;
    bool has_key = false;
    Node* parent = nullptr;
    std::vector<std::unique_ptr<Node>> children;
    bool expanded = false;
    bool table_view = false;
    int focus_index = 0;
};

inline std::string quote_string(const std::string& raw) {
    std::string out = "\"";
    for (unsigned char c : raw) {
        switch (c) {
            case '"': out += "\\\""; break;
            case '\\': out += "\\\\"; break;
            case '\b': out += "\\b"; break;
            case '\f': out += "\\f"; break;
            case '\n': out += "\\n"; break;
            case '\r': out += "\\r"; break;
            case '\t': out += "\\t"; break;
            default:
                if (c < 0x20) {
                    char buf[8];
                    std::snprintf(buf, sizeof(buf), "\\u%04x", c);
                    out += buf;
                } else {
                    out += static_cast<char>(c);
                }
        }
    }
    out += "\"";
    return out;
}

inline std::string value_repr(const json::Value& v) {
    switch (v.type) {
        case json::Type::Null: return "null";
        case json::Type::Bool: return v.boolean ? "true" : "false";
        case json::Type::String: return quote_string(v.str);
        case json::Type::Int:
        case json::Type::UInt:
        case json::Type::Double: return json::dump_number(v);
        default: return "";
    }
}

inline int value_color(const json::Value& v) {
    switch (v.type) {
        case json::Type::Null: return 9;   // red light
        case json::Type::Bool: return 11;  // yellow light
        case json::Type::String: return 10;  // green light
        case json::Type::Int:
        case json::Type::UInt:
        case json::Type::Double: return 14;  // cyan light
        default: return -1;
    }
}

inline std::unique_ptr<Node> build_tree(const json::Value& v, Node* parent) {
    auto n = std::make_unique<Node>();
    n->v = &v;
    n->parent = parent;
    if (v.is_object() || v.is_array()) {
        const json::Array* arr = nullptr;
        const json::Object* obj = nullptr;
        if (v.is_object()) obj = v.obj.get();
        else arr = v.arr.get();
        size_t count = v.is_object() ? obj->size() : arr->size();
        n->children.reserve(count);
        for (size_t i = 0; i < count; i++) {
            std::unique_ptr<Node> child;
            if (v.is_object()) {
                child = build_tree(obj->at(i).second, n.get());
                child->key = obj->at(i).first;
                child->has_key = true;
            } else {
                child = build_tree(arr->at(i), n.get());
            }
            n->children.push_back(std::move(child));
        }
    }
    return n;
}

inline void init_expand(Node* n, int depth) {
    if (!n->v) return;
    if (n->v->is_object() || n->v->is_array()) {
        bool is_array = n->v->is_array();
        if (depth == 0) {
            n->expanded = true;
        } else if (depth == 1) {
            n->expanded = !is_array;
        } else {
            n->expanded = false;
        }
        for (auto& c : n->children) init_expand(c.get(), depth + 1);
    }
}

inline bool all_objects(const json::Value& v) {
    if (!v.is_array()) return false;
    for (auto& e : *v.arr)
        if (!e.is_object()) return false;
    return true;
}

inline bool has_table_hint(const json::Value& v) {
    if (!all_objects(v)) return false;
    size_t n = v.arr->size();
    std::set<std::string> keys;
    for (auto& e : *v.arr)
        for (auto& m : *e.obj) keys.insert(m.first);
    if (n == 0) return false;
    return n > 1 || keys.size() > 1;
}

