                    for (size_t c = fi; c < l.table_cells.size(); c++) {
                        int s2 = l.table_cells[c];
                        int e2 = (c + 1 < l.table_cells.size()) ? l.table_cells[c + 1] - 1
                                                                : static_cast<int>(r.cells.size());
                        bool nonempty = false;
                        for (int x = s2; x < e2 && x < static_cast<int>(r.cells.size()); x++) {
                            if (r.cells[x].ch != " ") { nonempty = true; break; }
                        }
                        if (nonempty) { c0 = static_cast<int>(c); break; }
                    }
                    int s3 = l.table_cells[c0];
                    int e3 = (c0 + 1 < l.table_cells.size()) ? l.table_cells[c0 + 1] - 1
                                                             : static_cast<int>(r.cells.size());
                    for (int x = s3; x < e3 && x < static_cast<int>(r.cells.size()); x++) {
                        r.cells[x].style.invert = true;
                        r.cells[x].style.bold = false;
                    }
                } else if (cell_sel) {
                    // invert from the first value cell to the end of the value
                    int pre = l.prefix_width;
                    for (int x = pre; x < static_cast<int>(r.cells.size()); x++) {
                        if (r.cells[x].style.bold || r.cells[x].style.fg >= 0) {
                            r.cells[x].style.invert = true;
                            r.cells[x].style.bold = false;
                        } else if (r.cells[x].ch == ",") {
                            break;
                        }
                    }
                }
            }
        }
    }

