    Screen paint() {
        Screen s;
        s.init(screen_w, screen_h);
        for (int y = 0; y < screen_h; y++) {
            int ry = y + scroll;
            if (ry < 0 || ry >= static_cast<int>(rows.size())) continue;
            const Row& r = rows[ry];
            int x = 0;
            for (auto& c : r.cells) {
                if (x >= screen_w) break;
                s.at(x, y) = c;
                x += c.width;
            }
            for (; x < screen_w; x++) {
                Cell blank;
                blank.ch = " ";
                s.at(x, y) = blank;
            }
        }
        return s;
    }

