    std::fputs("\0\r\n", stdout);
    std::fflush(stdout);
    tcsetattr(0, TCSANOW, old);
}

static bool get_terminal_size(int& w, int& h) {
    struct winsize ws;
    if (ioctl(STDOUT_FILENO, TIOCGWINSZ, &ws) != 0) return false;
    if (ws.ws_col <= 0 || ws.ws_row <= 0) return false;
    w = ws.ws_col;
    h = ws.ws_row;
    return true;
}

int main(int argc, char** argv) {
    bool fullscreen = false;
    std::string filename;
    for (int i = 1; i < argc; i++) {
        std::string a = argv[i];
        if (a == "--") {
            for (int j = i + 1; j < argc; j++) filename = argv[j];
            break;
        }
        if (a == "-h" || a == "--help") { std::fputs(kHelp, stdout); return 0; }
        if (a == "-v" || a == "--version") { std::fputs("1.4.1\n", stdout); return 0; }
        if (a == "-k" || a == "--key" || a == "--keybinding") { std::fputs(kKeys, stdout); return 0; }
        if (a == "-f" || a == "--fullscreen") { fullscreen = true; continue; }
        if (!a.empty() && a[0] == '-') {
            std::fputs("Invalid arguments\n", stderr);
            return 1;
        }
        filename = a;
    }
    std::string data;
    if (filename.empty()) {
        char buf[65536];
        ssize_t n;
        while ((n = read(0, buf, sizeof(buf))) > 0) data.append(buf, n);
    } else {
        FILE* f = std::fopen(filename.c_str(), "rb");
        if (!f) {
            std::fputs("Could not open file ", stderr);
            std::fputs(filename.c_str(), stderr);
            std::fputs("\n", stderr);
            return 1;
        }
        char buf[65536];
        size_t n;
        while ((n = std::fread(buf, 1, sizeof(buf), f)) > 0) data.append(buf, n);
        std::fclose(f);
    }
    auto parsed = json::parse(reinterpret_cast<const unsigned char*>(data.data()), data.size());
    if (!parsed.error.empty()) {
        std::fputs("\n", stderr);
        std::fputs(parsed.error.c_str(), stderr);
        std::fputs("\n", stderr);
        return 1;
    }
    static json::Value root_value = std::move(parsed.value);
    Node root;
    root.v = &root_value;
    root.children = std::move([](const json::Value& v) {
        return build_children(v, nullptr);
    }(root_value));
    (void)root;
    return 0;
}
