    if (n <= 0) return Event::Quit;
    if (c == 3) return Event::Quit;
    if (c == 27) {
        unsigned char b[8];
        n = read(0, b, 1);
        if (n <= 0) return Event::Quit;  // Escape alone
        if (b[0] != '[') return Event::Other;
        n = read(0, b, 1);
        if (n <= 0) return Event::Other;
        switch (b[0]) {
            case 'A': return Event::Up;
            case 'B': return Event::Down;
            case 'C': return Event::Right;
            case 'D': return Event::Left;
            default: {
                // consume remaining bytes of the sequence
                while (true) {
                    unsigned char d = 0;
                    if (read(0, &d, 1) <= 0) break;
                    if ((d >= '0' && d <= '9') || d == ';' || d == '?' || d == '<' || d == '$' || d == '>') continue;
